 async function findPin(){const pin=$('#recoverPin').value,results=$('#recoveryResults');if(!validPin(pin)){results.textContent='Enter a PIN of 4–12 digits.';return}results.textContent='Checking device and server recovery points…';let rows=storageRead().snapshots.filter(r=>r.data.save.pin===pin).map(r=>({...r,source:'This device'})),message='';if(window.CESAR_FIXTURE?.save.pin===pin)rows.push({name:'Cesar',level:34,at:CESAR_FIXTURE.exportedAt,data:C.clone(CESAR_FIXTURE),source:'Original Level-34 archive'});try{const remote=await api('recover',{pin});rows.push(...remote.snapshots.map(r=>({...r,source:'Save server'})))}catch(e){message=e.message}rows.sort((a,b)=>new Date(b.at)-new Date(a.at));saveChoice=rows;if(!results.isConnected)return;results.innerHTML=rows.map((r,i)=>`<div class="save-row"><div><b>${esc(r.name||r.data.save.name)} · Lv ${r.level||r.data.save.level}</b><small>${new Date(r.at).toLocaleString()} · ${esc(r.source)}</small></div><button data-restore="${i}">Load this snapshot</button></div>`).join('')||'<p class="muted">No matching saves were found here. Import your JSON backup if it came from another website.</p>';if(message)results.innerHTML+=`<p class="notice">${esc(message)} Device results above are still available.</p>`}
 async function cloudSaveLegacy(){const pin=$('#pinInput').value,feedback=$('#saveFeedback');if(!validPin(pin)){feedback.textContent='Enter a PIN of 4–12 digits.';return}S.pin=pin;checkpoint('Before server save');feedback.textContent='Saving a timestamped snapshot…';try{const data=serial(),r=await api('save',{pin,snapshot:{at:data.exportedAt,name:S.name,level:S.level,data}});if(feedback.isConnected)feedback.textContent='Saved to this server at '+new Date(r.at).toLocaleString()+'. Open this same server address on your other device and use PIN recovery.'}catch(e){if(feedback.isConnected)feedback.textContent=e.message+' Your device save is still available. Export a backup.'}}
